CREATE TABLE work_workspaces(id INTEGER PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,archived_at TEXT);
CREATE TABLE work_people(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES work_workspaces(id) ON DELETE RESTRICT,name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',is_self INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX work_self_person ON work_people(workspace_id) WHERE is_self=1;
CREATE TABLE work_projects(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES work_workspaces(id) ON DELETE RESTRICT,name TEXT NOT NULL,identifier TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL DEFAULT 'personal',lead_id INTEGER REFERENCES work_people(id) ON DELETE SET NULL,website_id INTEGER REFERENCES website_profiles(id) ON DELETE SET NULL,start_date TEXT,target_date TEXT,status TEXT NOT NULL DEFAULT 'active',next_issue INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(workspace_id,identifier));
CREATE TABLE work_states(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES work_projects(id) ON DELETE CASCADE,name TEXT NOT NULL,state_group TEXT NOT NULL,color TEXT NOT NULL,position INTEGER NOT NULL,UNIQUE(project_id,name));
CREATE TABLE work_labels(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES work_projects(id) ON DELETE CASCADE,name TEXT NOT NULL,color TEXT NOT NULL,UNIQUE(project_id,name));
CREATE TABLE work_cycles(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES work_projects(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',starts_on TEXT,ends_on TEXT,status TEXT NOT NULL DEFAULT 'planned',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE work_modules(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES work_projects(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',lead_id INTEGER REFERENCES work_people(id) ON DELETE SET NULL,target_date TEXT,status TEXT NOT NULL DEFAULT 'planned',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE work_issues(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES work_projects(id) ON DELETE RESTRICT,sequence INTEGER NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',state_id INTEGER NOT NULL REFERENCES work_states(id),priority INTEGER NOT NULL DEFAULT 0,cycle_id INTEGER REFERENCES work_cycles(id) ON DELETE SET NULL,module_id INTEGER REFERENCES work_modules(id) ON DELETE SET NULL,parent_id INTEGER REFERENCES work_issues(id) ON DELETE RESTRICT,start_date TEXT,due_date TEXT,estimate REAL,sort_order REAL NOT NULL DEFAULT 0,intake_status TEXT NOT NULL DEFAULT 'accepted',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,archived_at TEXT,deleted_at TEXT,UNIQUE(project_id,sequence));
CREATE INDEX work_issue_listing ON work_issues(project_id,deleted_at,archived_at,intake_status,state_id,sort_order);
CREATE TABLE work_issue_assignees(issue_id INTEGER NOT NULL REFERENCES work_issues(id) ON DELETE CASCADE,person_id INTEGER NOT NULL REFERENCES work_people(id) ON DELETE RESTRICT,PRIMARY KEY(issue_id,person_id));
CREATE TABLE work_issue_labels(issue_id INTEGER NOT NULL REFERENCES work_issues(id) ON DELETE CASCADE,label_id INTEGER NOT NULL REFERENCES work_labels(id) ON DELETE CASCADE,PRIMARY KEY(issue_id,label_id));
CREATE TABLE work_relations(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES work_projects(id) ON DELETE CASCADE,from_id INTEGER NOT NULL REFERENCES work_issues(id) ON DELETE RESTRICT,to_id INTEGER NOT NULL REFERENCES work_issues(id) ON DELETE RESTRICT,kind TEXT NOT NULL,UNIQUE(from_id,to_id,kind),CHECK(from_id<>to_id));
CREATE TABLE work_comments(id INTEGER PRIMARY KEY,issue_id INTEGER NOT NULL REFERENCES work_issues(id) ON DELETE RESTRICT,author_id INTEGER NOT NULL REFERENCES work_people(id),body TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted_at TEXT);
CREATE TABLE work_time_entries(id INTEGER PRIMARY KEY,issue_id INTEGER NOT NULL REFERENCES work_issues(id) ON DELETE RESTRICT,person_id INTEGER NOT NULL REFERENCES work_people(id),on_date TEXT NOT NULL,minutes INTEGER NOT NULL CHECK(minutes>0 AND minutes<=1440),notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE work_timers(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL UNIQUE REFERENCES work_workspaces(id),issue_id INTEGER NOT NULL REFERENCES work_issues(id),started_at INTEGER NOT NULL);
CREATE TABLE work_attachments(id INTEGER PRIMARY KEY,issue_id INTEGER NOT NULL REFERENCES work_issues(id) ON DELETE RESTRICT,document_id INTEGER NOT NULL UNIQUE REFERENCES documents(id) ON DELETE RESTRICT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE work_pages(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES work_projects(id) ON DELETE RESTRICT,title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,pinned INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted_at TEXT);
CREATE TABLE work_page_versions(id INTEGER PRIMARY KEY,page_id INTEGER NOT NULL REFERENCES work_pages(id),version INTEGER NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(page_id,version));
CREATE TABLE work_page_issues(page_id INTEGER NOT NULL REFERENCES work_pages(id),issue_id INTEGER NOT NULL REFERENCES work_issues(id),PRIMARY KEY(page_id,issue_id));
CREATE TABLE work_views(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES work_projects(id) ON DELETE CASCADE,name TEXT NOT NULL,layout TEXT NOT NULL,filters TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE work_favorites(workspace_id INTEGER NOT NULL REFERENCES work_workspaces(id),entity TEXT NOT NULL,entity_id INTEGER NOT NULL,PRIMARY KEY(workspace_id,entity,entity_id));
CREATE TABLE work_activity(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES work_projects(id),issue_id INTEGER REFERENCES work_issues(id),actor_id INTEGER NOT NULL REFERENCES work_people(id),event TEXT NOT NULL,detail TEXT NOT NULL,day TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX work_activity_project ON work_activity(project_id,id);
CREATE TABLE work_snapshots(project_id INTEGER NOT NULL REFERENCES work_projects(id),cycle_id INTEGER NOT NULL DEFAULT 0,day TEXT NOT NULL,total INTEGER NOT NULL,completed INTEGER NOT NULL,points REAL NOT NULL,PRIMARY KEY(project_id,cycle_id,day));
